-- Local fixture only; validates private invitations/receipts without provider calls.
begin;
create temporary table mif(actor uuid,viewer uuid,wid uuid,sid uuid,meeting uuid,request uuid,coord uuid,content uuid,quality uuid,claim uuid);
insert into mif values(gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid());
insert into auth.users(id) select actor from mif union all select viewer from mif;
insert into public.bizoveya_workspaces(id,owner_id,name) select wid,actor,'Invitation fixture' from mif;
insert into public.bizoveya_memberships(workspace_id,user_id,role) select wid,actor,'owner' from mif union all select wid,viewer,'viewer' from mif;
insert into public.bizoveya_sites(id,workspace_id,name,mode,kind,status,created_by) select sid,wid,'Invitation site','native_business','business','active',actor from mif;
create function pg_temp.iexpect(q text,n text) returns void language plpgsql as $$begin begin execute q;exception when others then if strpos(sqlerrm,n)>0 then return;end if;raise;end;raise exception 'Expected %',n;end;$$;
do $$begin execute format('grant usage on schema %I to authenticated,service_role',(select nspname from pg_namespace where oid=pg_my_temp_schema()));end;$$;grant all on mif to authenticated,service_role;
set local role authenticated;select set_config('request.jwt.claim.sub',(select actor::text from mif),true);
select public.bz_agency_command(wid,sid,jsonb_build_object('action','meeting','id',meeting,'agenda','Distribute the approved launch decision.','mode','announcement','participants',jsonb_build_array('coordinator','content'),'reviewed',true,'inputMode','text')) from mif;
select public.bz_agency_command(wid,sid,jsonb_build_object('action','accept-decision','id',meeting,'expectedVersion',1,'reason','Prepare private launch drafts only.','reviewed',true)) from mif;
select public.bz_distribute_meeting_request(wid,sid,jsonb_build_object('id',meeting,'requestId',request,'expectedVersion',2,'instruction','Prepare the reviewed private drafts.','channels',jsonb_build_array('pinterest','linkedin'),'reviewed',true)) from mif;
select pg_temp.iexpect(format('select public.bz_invite_meeting_participants(%L,%L,%L)',wid,sid,jsonb_build_object('id',meeting,'expectedVersion',3,'reviewed',true)),'bz_site_roster_paused') from mif;
reset role;
insert into bizoveya_private.site_agent_rosters(site_id,version,document,actor_id) select sid,1,jsonb_build_object('enabled',true,'agents',jsonb_build_array(jsonb_build_object('kind','coordinator','agentId',coord,'agentVersion',4),jsonb_build_object('kind','content','agentId',content,'agentVersion',5),jsonb_build_object('kind','quality','agentId',quality,'agentVersion',6))),actor from mif;
set local role authenticated;select set_config('request.jwt.claim.sub',(select actor::text from mif),true);
select pg_temp.iexpect(format('select public.bz_invite_meeting_participants(%L,%L,%L)',wid,sid,jsonb_build_object('id',meeting,'expectedVersion',3,'reviewed',false)),'bz_invalid_meeting_invitation') from mif;
select public.bz_invite_meeting_participants(wid,sid,jsonb_build_object('id',meeting,'expectedVersion',3,'reviewed',true)) from mif;
select public.bz_invite_meeting_participants(wid,sid,jsonb_build_object('id',meeting,'expectedVersion',3,'reviewed',true)) from mif;
select set_config('request.jwt.claim.sub',(select viewer::text from mif),true);
select public.bz_agency_inventory(wid,sid) from mif;
select pg_temp.iexpect(format('select public.bz_invite_meeting_participants(%L,%L,%L)',wid,sid,jsonb_build_object('id',meeting,'expectedVersion',3,'reviewed',true)),'bz_forbidden') from mif;
select pg_temp.iexpect('select * from bizoveya_private.meeting_participant_invitations','permission denied');
reset role;
do $$declare j jsonb;begin j:=bizoveya_private.agency_json((select meeting from mif));if j#>>'{meetingInvitations,sourceVersion}'<>'3' or j#>>'{meetingInvitations,rosterVersion}'<>'1' or jsonb_array_length(j#>'{meetingInvitations,participants}')<>2 then raise exception 'Invitation projection mismatch';end if;if (select version from bizoveya_private.agency_records where id=(select meeting from mif))<>4 or (select count(*) from bizoveya_private.meeting_participant_receipts where action='invited')<>2 then raise exception 'Invitation retry duplicated effects';end if;if exists(select 1 from bizoveya_private.generation_runs) then raise exception 'Invitation executed work';end if;end;$$;
set local role service_role;
select pg_temp.iexpect(format('select public.bz_claim_meeting_invitation(%L,''coordinator'',%L,%L,4)',meeting,claim,content),'bz_forbidden') from mif;
select public.bz_claim_meeting_invitation(meeting,'coordinator',claim,coord,4) from mif;
select public.bz_claim_meeting_invitation(meeting,'coordinator',claim,coord,4) from mif;
select public.bz_finish_meeting_invitation(meeting,'coordinator',claim,coord,4,'acknowledged','Packet received; no task execution started.') from mif;
select public.bz_finish_meeting_invitation(meeting,'coordinator',claim,coord,4,'acknowledged','Packet received; no task execution started.') from mif;
select pg_temp.iexpect(format('select public.bz_finish_meeting_invitation(%L,''content'',%L,%L,5,''acknowledged'',''Forged without claim.'')',meeting,claim,content),'bz_conflict') from mif;
reset role;
do $$begin if (select state from bizoveya_private.meeting_participant_invitations where meeting_id=(select meeting from mif) and role='coordinator')<>'acknowledged' or (select count(*) from bizoveya_private.meeting_participant_receipts where role='coordinator' and action='claimed')<>1 or (select count(*) from bizoveya_private.meeting_participant_receipts where role='coordinator' and action='acknowledged')<>1 then raise exception 'Explicit receipt transition mismatch';end if;end;$$;
insert into bizoveya_private.meeting_participant_receipts(meeting_id,role,action,claim,agent_id,agent_version,note) select meeting,'content','claimed',gen_random_uuid(),content,5,'Synthetic local quota event.' from mif cross join generate_series(1,17);
set local role service_role;select pg_temp.iexpect(format('select public.bz_claim_meeting_invitation(%L,''content'',%L,%L,5)',meeting,gen_random_uuid(),content),'bz_meeting_receipt_limit') from mif;reset role;
select pg_temp.iexpect('update bizoveya_private.meeting_participant_receipts set note=''forged''','bz_immutable_agency_handoff');
delete from public.bizoveya_sites where id=(select sid from mif);
do $$begin if exists(select 1 from bizoveya_private.meeting_invitation_batches) or exists(select 1 from bizoveya_private.meeting_participant_invitations) or exists(select 1 from bizoveya_private.meeting_participant_receipts) then raise exception 'Invitation cascade failed';end if;end;$$;
rollback;
